function esc15(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function cap15(s){s=String(s||'');return s.charAt(0).toUpperCase()+s.slice(1);}
function vePhoto(k){var p=PHOTOS[k];return p?'<img src="'+p.url+'" alt="'+esc15(p.caption)+'" loading="lazy" class="photo-thumb" onclick="openLightbox(\''+k+'\')" onerror="this.classList.add(\'photo-error\')">':'';}
function veRow(ks){return '<div class="photo-row">'+(ks||[]).map(vePhoto).join('')+'</div>';}
function R(a){return{id:a[0],brand:a[1],models:a[2],years:a[3],energy:a[4],motor:a[5],subsys:a[6]||'',cause:a[7],mech:a[8],idx:a[9],src:a[10],ref:a[11]||'-',power:a[12]||'',photos:a[13]||[]};}

