function recallCard(r){var en={thermal:"🚗 Thermique",ev:"🔋 Électrique",hybrid:"🔄 Hybride",lpg:"⛽ GPL"}[r.energy]||r.energy;
return '<div class="cause-card"><span class="category-badge">'+en+'</span><span class="badge-src">'+esc15(r.src)+'</span><h3>'+esc15(r.brand)+'</h3><p class="cause-type">'+esc15(r.models)+' • '+esc15(r.years)+'</p><p class="cause-desc"><strong>Motorisation :</strong> '+esc15(r.motor)+' • <strong>Réf :</strong> '+esc15(r.ref)+'</p><p class="cause-desc"><strong>Panne :</strong> '+esc15(r.cause)+'</p>'+veRow(r.photos)+'<button class="btn-expand" onclick="expandRecall(\''+r.id+'\')">🎓 Mode formation complet</button></div>';}
function renderRecalls(list){var g=document.getElementById('recallGrid');if(!g)return;
g.innerHTML=list.length?list.map(recallCard).join(''):'<p class="no-results">Aucun rappel trouvé</p>';
var s=document.getElementById('recallStats');if(s)s.textContent=list.length+' campagne(s) affichée(s) / '+RECALLS.length+' référencées (base + feed mensuel).';}
function expandRecall(id){var r=RECALLS.find(function(x){return x.id===id;});if(!r)return;var m=document.createElement('div');m.className='modal-overlay';
m.innerHTML='<div class="modal-content"><button class="modal-close" onclick="this.closest(\'.modal-overlay\').remove()">×</button><h2>🎓 '+esc15(r.brand)+' — '+esc15(r.models)+'</h2><div class="modal-section"><h3>Fiche</h3><p><strong>Années :</strong> '+esc15(r.years)+'<br><strong>Motorisation :</strong> '+esc15(r.motor)+'<br><strong>Source :</strong> '+esc15(r.src)+' — <strong>Réf :</strong> '+esc15(r.ref)+'</p></div><div class="modal-section"><h3>1. Origine : la panne</h3><p>'+esc15(r.cause)+'</p></div><div class="modal-section"><h3>2. Inflammation → propagation</h3><p>'+esc15(r.mech)+'</p></div><div class="modal-section"><h3>3. Indices thermiques & fusion</h3><p class="identification">'+esc15(r.idx)+'</p></div><div class="modal-section"><h3>4. Photos</h3><div class="photo-row big">'+veRow(r.photos)+'</div></div></div>';
document.body.appendChild(m);}

