var ELROQ_SUBS=['Tous','batt','charge','range','adas','camera','software','mech','overheat','elec','cabin'];
function renderElroqGrid(sub,q){var g=document.getElementById('elroqGrid');if(!g)return;
 var l=ELROQ.filter(function(x){if(sub&&sub!=='Tous'&&x.subsys!==sub)return false;
  if(q){var hay=seNorm(x.cause+' '+x.mech+' '+x.idx+' '+x.models);return seNorm(q).split(/[\s,]+/).filter(Boolean).every(function(t){return hay.indexOf(t)>=0;});}
  return true;});
 var c=document.getElementById('elroqChips');if(c)c.innerHTML=ELROQ_SUBS.map(function(s){return '<button class="nav-btn '+(s===sub?'active':'')+'" data-elq="'+s+'">'+(TITRES[s]||s)+'</button>';}).join('');
 var n=document.getElementById('elroqCount');if(n)n.textContent=l.length+' symptôme(s) Elroq / '+ELROQ.length;
 g.innerHTML=l.length?l.map(function(x){return dbCardElroq(x);}).join(''):'<p class="no-results">Aucun symptôme</p>';}
function dbCardElroq(x){return '<div class="cause-card"><span class="category-badge">🟢 '+(TITRES[x.subsys]||x.subsys)+'</span><span class="badge-src">'+esc15(x.src)+'</span><h3>'+esc15(x.models)+'</h3><p class="cause-type">'+esc15(x.motor)+' • '+esc15(x.years)+'</p><p class="cause-desc"><strong>Symptôme :</strong> '+esc15(x.cause)+'</p><p class="cause-desc"><strong>Mécanisme :</strong> '+esc15(x.mech)+'</p><p class="identification"><strong>Indice :</strong> '+esc15(x.idx)+'</p>'+veRow(x.photos)+'</div>';}

